# posts/tests.py
from django.test import TestCase
from .models import Post

class PostModelTest(TestCase):
    def setUp(self):
        self.post = Post.objects.create(title="Привет", slug="hello", body="Текст")

    def test_str_returns_title(self):
        self.assertEqual(str(self.post), "Привет")

